  footer=f'<footer class="footer"><div class="eyebrow">{s("location")}</div>{s("footerTitle","h2")}<a class="footer-cta" href="{home}#contact" data-home="#contact">{s("start")} ↗</a><div class="footer-bottom">{brand}<div><a href="tel:+77022950040">+7 702 295 00 40</a><a href="https://wa.me/77022950040" data-event="whatsapp_click">WhatsApp ↗</a><a href="https://t.me/rakishovbot" data-event="telegram_click">Telegram ↗</a></div></div><div class="copyright"><span>© 2026 Sabir Rakishov</span>{s("rights")}</div></footer>'
