  page=f'''<!doctype html><html lang="{'kk' if lang=='kz' else lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><meta name="description" content="{E(desc,quote=True)}"><meta name="theme-color" content="#f5f4ef"><meta name="robots" content="{'noindex,nofollow' if admin else 'index,follow'}"><link rel="canonical" href="{url}">{alternates}<meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta name="twitter:card" content="summary"><link rel="icon" type="image/svg+xml" sizes="any" href="{root}assets/favicon.svg?v=3"><link rel="stylesheet" href="{root}css/site.css">{('<link rel="stylesheet" href="'+root+'css/admin.css">') if admin else ''}<script defer src="{root}js/settings.js"></script><script defer data-sr-app src="{root}js/site.bundle.js"></script></head><body data-root="{root}" data-lang="{lang}" data-page="{kind}" data-route="{route}" {('data-project="'+pr['slug']+'"') if pr else ''} class="{'admin' if admin else ''}">{header}{main}{'' if admin else footer}<aside id="consent-banner" class="consent-banner" hidden>{s('analyticsConsent','p')}<div><button data-consent="yes" class="btn">{s('allow')}</button><button data-consent="no" class="text-btn">{s('decline')}</button></div></aside><button id="back-to-top" class="back-to-top" type="button" aria-label="{attr('backToTop')}" data-label="backToTop" hidden><span aria-hidden="true">↑</span></button><div id="toast" class="toast" role="status" hidden></div></body></html>'''
