(P/'404.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>404 — Sabir Rakishov</title><link rel="icon" type="image/svg+xml" href="assets/favicon.svg?v=3"><body style="font:24px sans-serif;background:#f5f4ef;padding:10vw"><h1>404</h1><p>Страница не найдена / Page not found</p><a href="'+ORIGIN+'/">Sabir Rakishov →</a></body></html>')
